#include "image_build.h"
#include "fib.h"

#include <algorithm>
#include <array>
#include <deque>
#include <map>
#include <stdexcept>
#include <vector>

/* ------------------------------------------------------------------ */
/* Node construction                                                   */
/* ------------------------------------------------------------------ */

namespace {

struct ExpNode {
    int origin = 0;
    int depth = 0;
    int level = 0;
    u128_t region = 0;
    int type = NODE_NONE;
    uint32_t owned = 0;
    /* local NI prefixes, increasing bitmap position */
    std::vector<uint8_t> lpos;
    std::vector<uint32_t> lhop;
    uint64_t pattern = 0;
    /* children, increasing key */
    std::vector<uint8_t> ckey;
    std::vector<int32_t> cidx;
    std::vector<unsigned char> cbulk;
    /* inline prefixes for TYPE4/TYPE5 */
    ScampPrefix inl[2];
    int ninl = 0;
    /* placement */
    int stage = 0;
    uint32_t cell = 0;
    int slot = 0;
    int rec = 0;
    bool bulk_root = false;
    /* packed fields */
    uint32_t bmp = SCAMP_BMP_NULL;
    uint32_t bitmap_id = 0;
    uint32_t ni_base = 0;
    int bulk_stage = 0;
    uint32_t bulk_base = 0;
    uint64_t bulk_bitmap = 0;
};

struct BuildCtx {
    const std::vector<ScampPrefix>* p = nullptr;
    std::deque<ExpNode> nodes;
};

int origin_rank(int len) {
    int o = scamp_origin(len);
    return o == 0 ? 0 : (o == 16 ? 1 : 2);
}

int exp_build(BuildCtx& c, int origin, u128_t region, int depth,
              const std::vector<int>& buf, int lo, int hi) {
    const std::vector<ScampPrefix>& P = *c.p;
    int idx = static_cast<int>(c.nodes.size());
    c.nodes.emplace_back();
    ExpNode& n = c.nodes[idx];
    n.origin = origin;
    n.depth = depth;
    n.level = (depth - origin) / 6;
    n.region = region;

    int count = hi - lo;
    if (count <= 0) throw std::runtime_error("empty export node");
    if (count <= 2) {
        n.type = (count == 1) ? TYPE4 : TYPE5;
        n.ninl = count;
        n.owned = static_cast<uint32_t>(count);
        for (int i = 0; i < count; ++i) n.inl[i] = P[buf[lo + i]];
        return idx;
    }

    int limit = depth + 6;
    int max = scamp_origin_max(origin);
    std::vector<std::pair<uint8_t, uint32_t> > locals;
    std::vector<int> rest;
    locals.reserve(count);
    rest.reserve(count);
    for (int i = lo; i < hi; ++i) {
        const ScampPrefix& pf = P[buf[i]];
        if (static_cast<int>(pf.len) < limit || limit > max) {
            int l = static_cast<int>(pf.len) - depth;
            if (l < 0 || l > 5) throw std::runtime_error("local length");
            uint32_t v = scamp_bits(pf.addr, depth, l);
            uint8_t pos = static_cast<uint8_t>((1u << l) + v);
            locals.push_back(std::make_pair(pos, pf.hop));
        } else {
            rest.push_back(buf[i]);
        }
    }
    std::sort(locals.begin(), locals.end());
    for (size_t i = 0; i < locals.size(); ++i) {
        if (i && locals[i].first == locals[i - 1].first) throw std::runtime_error("duplicate local");
        n.lpos.push_back(locals[i].first);
        n.lhop.push_back(locals[i].second);
        n.pattern |= (1ULL << locals[i].first);
    }

    int cnt[64] = {0};
    for (size_t i = 0; i < rest.size(); ++i) cnt[scamp_bits(P[rest[i]].addr, depth, 6)]++;
    std::vector<int> sorted(rest.size());
    int start[65];
    start[0] = 0;
    for (int k = 0; k < 64; ++k) start[k + 1] = start[k] + cnt[k];
    {
        int cur[64];
        for (int k = 0; k < 64; ++k) cur[k] = start[k];
        for (size_t i = 0; i < rest.size(); ++i) {
            int k = scamp_bits(P[rest[i]].addr, depth, 6);
            sorted[cur[k]++] = rest[i];
        }
    }
    if (limit <= max) {
        for (int k = 0; k < 64; ++k) {
            if (!cnt[k]) continue;
            u128_t cregion = region | (static_cast<u128_t>(k) << (128 - limit));
            int ci = exp_build(c, origin, cregion, limit, sorted, start[k], start[k + 1]);
            n.ckey.push_back(static_cast<uint8_t>(k));
            n.cidx.push_back(ci);
        }
    }
    int cc = static_cast<int>(n.ckey.size());
    n.type = (cc <= 2) ? TYPE1 : ((cc <= 6) ? TYPE2 : TYPE3);
    n.owned = static_cast<uint32_t>(n.lpos.size());
    for (int i = 0; i < cc; ++i) n.owned += c.nodes[n.cidx[i]].owned;
    if (n.owned != static_cast<uint32_t>(count)) throw std::runtime_error("owned mismatch");
    return idx;
}

void pack_inline(Row256& row, int& pos, const ScampPrefix& p, int origin) {
    uint64_t frag;
    uint32_t len;
    if (origin == 0) {
        frag = scamp_hi(p.addr);
        len = p.len;
    } else if (origin == 16) {
        frag = (scamp_hi(p.addr) & 0xFFFFFFFFFFFFULL) << 16;
        len = static_cast<uint32_t>(p.len) - 16u;
    } else {
        frag = scamp_lo(p.addr);
        len = static_cast<uint32_t>(p.len) - 64u;
    }
    pk_write(row, pos, frag, PK_INL_FRAG_BITS);
    pk_write(row, pos, len, PK_INL_LEN_BITS);
    pk_write(row, pos, p.hop, PK_INL_HOP_BITS);
}

} /* namespace */

/* ------------------------------------------------------------------ */
/* Image construction                                                  */
/* ------------------------------------------------------------------ */

ImageData build_image(const std::vector<ScampPrefix>& prefixes) {
    ImageData d;
    d.root.stage = -1;
    if (prefixes.empty()) return d;
    if (prefixes.size() > SCAMP_PREFIX_LIMIT) throw std::runtime_error("prefix bound");

    std::vector<ScampPrefix> P = prefixes;
    std::vector<int> order(P.size());
    for (size_t i = 0; i < P.size(); ++i) {
        P[i].addr = scamp_mask(P[i].addr, P[i].len);
        if (P[i].hop > SCAMP_HOP_MAX) throw std::runtime_error("hop bound");
        order[i] = static_cast<int>(i);
    }
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        const ScampPrefix& x = P[a];
        const ScampPrefix& y = P[b];
        int rx = origin_rank(x.len), ry = origin_rank(y.len);
        if (rx != ry) return rx < ry;
        uint64_t kx = scamp_front_key(x.addr, scamp_origin(x.len));
        uint64_t ky = scamp_front_key(y.addr, scamp_origin(y.len));
        if (kx != ky) return kx < ky;
        if (x.addr != y.addr) return x.addr < y.addr;
        return x.len < y.len;
    });

    BuildCtx c;
    c.p = &P;
    c.nodes.reserve(0);

    /* one tree per owner group */
    std::vector<int> root_of_group;      /* node index per group, in order */
    std::vector<int> group_rank;
    std::vector<uint64_t> group_key;
    size_t i = 0;
    while (i < order.size()) {
        size_t j = i;
        const ScampPrefix& first = P[order[i]];
        int rank = origin_rank(first.len);
        uint64_t key = scamp_front_key(first.addr, scamp_origin(first.len));
        while (j < order.size()) {
            const ScampPrefix& q = P[order[j]];
            if (origin_rank(q.len) != rank) break;
            if (scamp_front_key(q.addr, scamp_origin(q.len)) != key) break;
            ++j;
        }
        int origin = (rank == 0) ? 0 : (rank == 1 ? 16 : 64);
        u128_t region;
        if (origin == 0) region = 0;
        else if (origin == 16) region = static_cast<u128_t>(key) << 112;
        else region = static_cast<u128_t>(key) << 64;
        std::vector<int> items(order.begin() + i, order.begin() + j);
        int r = exp_build(c, origin, region, origin, items, 0, static_cast<int>(items.size()));
        root_of_group.push_back(r);
        group_rank.push_back(rank);
        group_key.push_back(key);
        i = j;
    }

    std::deque<ExpNode>& N = c.nodes;

    /* stages: level t of any forest lives at stage 10 - t, so every child
       stage is strictly lower than its parent stage and all bulk children of
       a TYPE3 share one stage. */
    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        n.stage = SCAMP_STAGE_MAX - n.level;
        n.rec = scamp_type_cells(n.type);
        if (n.stage < 0 || n.stage > SCAMP_STAGE_MAX) throw std::runtime_error("stage bound");
    }
    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        if (n.type != TYPE3) continue;
        int cc = static_cast<int>(n.ckey.size());
        int direct = std::min(3, cc - 4);
        if (direct < 0) throw std::runtime_error("type3 children");
        n.bulk_bitmap = 0;
        n.bulk_stage = n.stage - 1;
        for (int j = 0; j < cc; ++j) {
            unsigned char bulk = (j >= direct) ? 1 : 0;
            n.cbulk.push_back(bulk);
            if (bulk) {
                n.bulk_bitmap |= (1ULL << n.ckey[j]);
                N[n.cidx[j]].bulk_root = true;
            }
        }
    }
    for (size_t k = 0; k < N.size(); ++k) N[k].slot = N[k].bulk_root ? 2 : N[k].rec;

    /* cell allocation: two cell units first (keeps them even), then halves */
    std::array<uint32_t, RAM_NUM> cells{};
    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t cur = 0;
        for (size_t k = 0; k < N.size(); ++k) {
            ExpNode& n = N[k];
            if (n.bulk_root) continue;
            if (n.stage == s && n.slot == 2) { n.cell = cur; cur += 2; }
        }
        for (size_t k = 0; k < N.size(); ++k) {
            ExpNode& n = N[k];
            if (n.type != TYPE3 || n.bulk_stage != s) continue;
            n.bulk_base = cur;
            uint32_t b = 0;
            for (size_t j = 0; j < n.ckey.size(); ++j) {
                if (!n.cbulk[j]) continue;
                ExpNode& ch = N[n.cidx[j]];
                ch.stage = s;
                ch.cell = cur + 2 * b;
                ++b;
            }
            cur += 2 * b;
        }
        for (size_t k = 0; k < N.size(); ++k) {
            ExpNode& n = N[k];
            if (n.bulk_root) continue;
            if (n.stage == s && n.slot == 1) { n.cell = cur; cur += 1; }
        }
        cells[s] = cur;
        if (cur > SCAMP_CELL_LIMIT) throw std::runtime_error("cell bound");
    }

    /* global BMP fallbacks */
    LiveFib fib;
    for (size_t k = 0; k < P.size(); ++k) fib.put(P[k].addr, P[k].len, P[k].hop);
    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        nexthop_t v = fib.lookup_bounded(n.region, n.depth);
        n.bmp = (v == LPM_INVALID_NH) ? SCAMP_BMP_NULL : static_cast<uint32_t>(v);
    }

    /* NI dictionary and NI array */
    std::vector<uint64_t> used;
    std::vector<uint32_t> ni;
    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        if (n.type > TYPE3) continue;
        used.push_back(n.pattern);
        if (n.pattern == 0) {
            n.ni_base = 0;
        } else {
            n.ni_base = static_cast<uint32_t>(ni.size());
            for (size_t j = 0; j < n.lhop.size(); ++j) ni.push_back(n.lhop[j]);
        }
    }
    std::sort(used.begin(), used.end());
    used.erase(std::unique(used.begin(), used.end()), used.end());
    if (used.size() > SCAMP_BITMAP_LIMIT) throw std::runtime_error("dictionary bound");
    if (ni.size() > SCAMP_NI_LIMIT) throw std::runtime_error("NI bound");
    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        if (n.type > TYPE3) continue;
        n.bitmap_id = static_cast<uint32_t>(
            std::lower_bound(used.begin(), used.end(), n.pattern) - used.begin());
    }
    d.bitmaps = used;
    d.nexthops = ni;

    /* physical rows */
    uint64_t total_rows = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t rows = (cells[s] + 1) / 2;
        d.banks[s].assign(rows, Row256());
        total_rows += rows;
    }
    if (total_rows > SCAMP_ROW_LIMIT) throw std::runtime_error("row bound");
    d.cells = cells;

    for (size_t k = 0; k < N.size(); ++k) {
        ExpNode& n = N[k];
        Row256& row = d.banks[n.stage][n.cell / 2];
        int base = (n.rec == 2) ? 0 : ((n.cell & 1u) ? 128 : 0);
        int pos = base;
        pk_write(row, pos, static_cast<uint64_t>(n.type), PK_TYPE_BITS);
        pk_write(row, pos, n.bmp, PK_BMP_BITS);
        if (n.type == TYPE1 || n.type == TYPE2 || n.type == TYPE3) {
            pk_write(row, pos, n.bitmap_id, PK_BID_BITS);
            pk_write(row, pos, n.ni_base, PK_NIB_BITS);
        }
        if (n.type == TYPE1 || n.type == TYPE2) {
            int slots = (n.type == TYPE1) ? 2 : 6;
            int cc = static_cast<int>(n.ckey.size());
            for (int j = 0; j < slots; ++j) {
                if (j < cc) {
                    ExpNode& ch = N[n.cidx[j]];
                    pk_write(row, pos, pk_child_value(n.ckey[j], ch.stage, ch.cell), 32);
                } else {
                    pk_write(row, pos, SCAMP_CHILD_ABSENT, 32);
                }
            }
        } else if (n.type == TYPE3) {
            pk_write(row, pos, n.bulk_bitmap, PK_BULK_BM_BITS);
            pk_write(row, pos, n.bulk_base, PK_BULK_BASE_BITS);
            pk_write(row, pos, static_cast<uint64_t>(n.bulk_stage), PK_BULK_STG_BITS);
            int written = 0;
            for (size_t j = 0; j < n.ckey.size() && written < 3; ++j) {
                if (n.cbulk[j]) continue;
                ExpNode& ch = N[n.cidx[j]];
                pk_write(row, pos, pk_child_value(n.ckey[j], ch.stage, ch.cell), 32);
                ++written;
            }
            while (written < 3) { pk_write(row, pos, SCAMP_CHILD_ABSENT, 32); ++written; }
        } else if (n.type == TYPE4) {
            pack_inline(row, pos, n.inl[0], n.origin);
        } else if (n.type == TYPE5) {
            pack_inline(row, pos, n.inl[0], n.origin);
            pack_inline(row, pos, n.inl[1], n.origin);
        }
    }

    /* roots and fronts */
    for (size_t g = 0; g < root_of_group.size(); ++g) {
        ExpNode& r = N[root_of_group[g]];
        ImageLoc loc;
        loc.stage = r.stage;
        loc.cell = r.cell;
        if (group_rank[g] == 0) {
            d.root = loc;
        } else if (group_rank[g] == 1) {
            ImageFront f; f.key = group_key[g]; f.loc = loc;
            d.front16.push_back(f);
        } else {
            ImageFront f; f.key = group_key[g]; f.loc = loc;
            d.front64.push_back(f);
        }
    }
    if (d.front16.size() > SCAMP_FRONT_LIMIT || d.front64.size() > SCAMP_FRONT_LIMIT)
        throw std::runtime_error("front bound");
    return d;
}
